style.css:
/* Google Windows 7 LEVE */

body {
    background: url("https://wallpapercave.com/wp/wp2757874.jpg") center center fixed !important;
    background-size: cover !important;
}

/* Barra de pesquisa */
textarea,
input,
[role="combobox"] {
    background: white !important;
    border-radius: 25px !important;
    border: 1px solid #ccc !important;
}

/* REMOVE blur pesado */
div,
header,
footer {
    backdrop-filter: none !important;
}
